import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.Nk14N-ai.js";const k=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting_started.md","filePath":"getting_started.md"}'),n={name:"getting_started.md"};function o(r,e,l,h,p,d){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><blockquote><p><strong>Two paths. Pick yours.</strong></p><ul><li><strong><a href="#path-a-deploy-your-own-network">Deploying your own network?</a></strong> → You want <code>kinetic-forge</code>.</li><li><strong><a href="#path-b-use-the-kin-network">Using the <code>.kin</code> public network?</a></strong> → You want <code>kinetic-daemon</code>.</li></ul></blockquote><hr><h2 id="system-prerequisites" tabindex="-1">System Prerequisites <a class="header-anchor" href="#system-prerequisites" aria-label="Permalink to &quot;System Prerequisites&quot;">​</a></h2><p>Both paths require the same toolchain.</p><h3 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to &quot;Required&quot;">​</a></h3><ol><li><strong>Rust toolchain</strong> — install via <a href="https://rustup.rs/" target="_blank" rel="noreferrer">rustup</a></li><li><strong>C++ compiler</strong> — required by the <code>chiavdf</code> FFI bindings (<code>g++</code> or <code>clang</code>)</li><li><strong>GMP library</strong> — the Chia VDF engine uses GNU Multiple Precision Arithmetic for large integer math</li></ol><p><strong>Ubuntu / Debian:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-essential</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libgmp-dev</span></span></code></pre></div><p><strong>macOS (Homebrew):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmp</span></span></code></pre></div><h3 id="clone-and-build" tabindex="-1">Clone and Build <a class="header-anchor" href="#clone-and-build" aria-label="Permalink to &quot;Clone and Build&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/saifmukhtar/kinetic.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kinetic</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span></code></pre></div><blockquote><p>⚠️ Always build in <code>--release</code> mode. The VDF computation is highly sensitive to compiler optimizations — debug mode makes name registrations unbearably slow.</p></blockquote><hr><h2 id="path-a-deploy-your-own-network" tabindex="-1">Path A: Deploy Your Own Network <a class="header-anchor" href="#path-a-deploy-your-own-network" aria-label="Permalink to &quot;Path A: Deploy Your Own Network&quot;">​</a></h2><blockquote><p><em>For universities, companies, governments, and communities who want a sovereign namespace under their own TLD.</em></p></blockquote><h3 id="step-1-run-kinetic-forge" tabindex="-1">Step 1: Run <code>kinetic-forge</code> <a class="header-anchor" href="#step-1-run-kinetic-forge" aria-label="Permalink to &quot;Step 1: Run \`kinetic-forge\`&quot;">​</a></h3><p><code>kinetic-forge</code> is the interactive wizard that generates your <code>network.json</code> — the single file that defines your entire network identity.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/release/kinetic-forge</span></span></code></pre></div><p>It will ask you for:</p><ul><li>Your TLD (e.g. <code>uni</code>, <code>acme</code>, <code>internal</code>)</li><li>Your organization&#39;s base domain</li><li>VDF difficulty (it will benchmark your hardware automatically)</li><li>Name recycling period (how long idle names survive)</li><li>Whether to enable Phase 2 governance auto-lock</li></ul><p>When it finishes, you will have:</p><ul><li>A fully configured <code>network.json</code></li><li>A generated governance keypair in <code>./keys/</code> — <strong>keep these offline</strong></li></ul><h3 id="step-2-recompile-with-your-network-config" tabindex="-1">Step 2: Recompile with Your Network Config <a class="header-anchor" href="#step-2-recompile-with-your-network-config" aria-label="Permalink to &quot;Step 2: Recompile with Your Network Config&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span></span></code></pre></div><p>All binaries now have your network&#39;s constants compiled in. Every node your users run will share identical cryptographic constants — there is no runtime config drift possible.</p><h3 id="step-3-launch-your-bootstrap-nodes" tabindex="-1">Step 3: Launch Your Bootstrap Nodes <a class="header-anchor" href="#step-3-launch-your-bootstrap-nodes" aria-label="Permalink to &quot;Step 3: Launch Your Bootstrap Nodes&quot;">​</a></h3><p>Run <code>kinetic-node</code> on at least two stable servers. These are the DHT entry points for everyone on your network:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On your server:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./target/release/kinetic-node</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The peer ID is printed to stdout when kinetic-node starts.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># You can also retrieve it from the node&#39;s local API:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">node_api_por</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/peer_id</span></span></code></pre></div><p>Update <code>bootstrap_nodes</code> in your <code>network.json</code> with these addresses, recompile, and distribute the binaries to your users.</p><h3 id="step-4-distribute" tabindex="-1">Step 4: Distribute <a class="header-anchor" href="#step-4-distribute" aria-label="Permalink to &quot;Step 4: Distribute&quot;">​</a></h3><p>Users on your network install <code>kinetic-daemon</code> and <code>kinetic-cli</code> built from your <code>network.json</code>. They run the daemon, register names under your TLD, and resolve them natively in their browser — same workflow as the <code>.kin</code> network, but entirely under your control.</p><p>→ <strong>Full details:</strong> <a href="./forking.html">Fork Your Own Network</a></p><hr><h2 id="path-b-use-the-kin-network" tabindex="-1">Path B: Use the <code>.kin</code> Network <a class="header-anchor" href="#path-b-use-the-kin-network" aria-label="Permalink to &quot;Path B: Use the \`.kin\` Network&quot;">​</a></h2><blockquote><p><em>For developers and builders using the canonical public network — no operator, no fees, no permission required.</em></p></blockquote><h3 id="step-1-launch-the-daemon" tabindex="-1">Step 1: Launch the Daemon <a class="header-anchor" href="#step-1-launch-the-daemon" aria-label="Permalink to &quot;Step 1: Launch the Daemon&quot;">​</a></h3><p>The <code>kinetic-daemon</code> runs continuously in the background. It handles:</p><ul><li>Your local Kademlia DHT peer connection to the <code>.kin</code> network</li><li>Split-DNS on port <code>53</code> — intercepts <code>.kin</code> queries, passes everything else through</li><li>Local REST API on <code>127.0.0.1:16001</code></li></ul><p>Because binding port <code>53</code> is a privileged operation on Linux and macOS, run with <code>sudo</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./target/release/kinetic-daemon</span></span></code></pre></div><p>Once running, the daemon logs will confirm it has connected to the bootstrap DHT swarm and initialized the local Sled database.</p><hr><h3 id="step-2-register-your-name-two-phase-protocol" tabindex="-1">Step 2: Register Your Name (Two-Phase Protocol) <a class="header-anchor" href="#step-2-register-your-name-two-phase-protocol" aria-label="Permalink to &quot;Step 2: Register Your Name (Two-Phase Protocol)&quot;">​</a></h3><p>Kinetic uses a <strong>Commit → Grind → Reveal</strong> protocol to prevent front-running. No one can snipe your name during the VDF computation because the commitment is blind.</p><h4 id="phase-1-commit-grind" tabindex="-1">Phase 1: Commit &amp; Grind <a class="header-anchor" href="#phase-1-commit-grind" aria-label="Permalink to &quot;Phase 1: Commit &amp; Grind&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kinetic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.kin</span></span></code></pre></div><p>What happens:</p><ol><li>The CLI fetches the latest <code>drand</code> Quicknet pulse (the randomness beacon)</li><li>Hashes your name + random salt + drand pulse + your Ed25519 public key into a blind commitment and broadcasts it to the DHT instantly</li><li>Starts the VDF computation — your CPU will run at full load. Time depends on name length:</li></ol><table tabindex="0"><thead><tr><th>Name length</th><th>Approximate time</th></tr></thead><tbody><tr><td>8+ characters</td><td>~2 hours</td></tr><tr><td>6 characters</td><td>~12 hours</td></tr><tr><td>5 characters</td><td>~1 day</td></tr><tr><td>4 characters</td><td>~15 days</td></tr></tbody></table><ol start="4"><li>When done, saves your proof to <code>~/.config/kinetic/zones/example.kin.reveal.json</code></li></ol><h4 id="phase-2-configure-publish" tabindex="-1">Phase 2: Configure &amp; Publish <a class="header-anchor" href="#phase-2-configure-publish" aria-label="Permalink to &quot;Phase 2: Configure &amp; Publish&quot;">​</a></h4><p>Open <code>~/.config/kinetic/zones/example.kin.json</code> and add your DNS records:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;example.kin.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;records&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_SERVER_IP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;target_kid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;did:kin:kid1abc9f7...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Then publish to the global network:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kinetic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.kin</span></span></code></pre></div><p>Your name is live globally. Any device running the Kinetic daemon can now resolve <code>example.kin</code>.</p><hr><h3 id="step-3-test-resolution" tabindex="-1">Step 3: Test Resolution <a class="header-anchor" href="#step-3-test-resolution" aria-label="Permalink to &quot;Step 3: Test Resolution&quot;">​</a></h3><p><strong>Via <code>dig</code>:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @127.0.0.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.kin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> A</span></span></code></pre></div><p>You should get an instant response with your <code>A</code> record.</p><p><strong>Via browser:</strong> Open <code>http://example.kin</code> directly in Chrome or Firefox. The daemon intercepts the DNS query transparently — no browser extension needed.</p><p><strong>Verify legacy traffic still works:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @127.0.0.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> A</span></span></code></pre></div><p>The daemon recognizes <code>github.com</code> does not end in <code>.kin</code> and forwards it to your <strong>OS system DNS resolver</strong> (read from your system config via <code>read_system_conf()</code>). If the system config cannot be read, it falls back to Cloudflare DNS. Normal internet is unaffected.</p><hr><h3 id="step-4-keep-your-name-alive-heartbeat" tabindex="-1">Step 4: Keep Your Name Alive (Heartbeat) <a class="header-anchor" href="#step-4-keep-your-name-alive-heartbeat" aria-label="Permalink to &quot;Step 4: Keep Your Name Alive (Heartbeat)&quot;">​</a></h3><p>Ownership is maintained by a continuous cryptographic heartbeat — a signature broadcast to the DHT proving your node is online. The daemon handles this automatically while it runs.</p><p>If your daemon goes offline for an extended period, the name enters <strong>Grace-Period Escalation</strong> — attackers must compute an exponentially harder VDF to challenge it, and you can reclaim it instantly by bringing your daemon back online during the challenge window.</p><p>→ <strong>Full details:</strong> <a href="./hybrid_lease_system.html">VDF Delegation, Heartbeats &amp; Lease System</a></p><hr><h2 id="the-kinetic-ui-dashboard" tabindex="-1">The Kinetic UI Dashboard <a class="header-anchor" href="#the-kinetic-ui-dashboard" aria-label="Permalink to &quot;The Kinetic UI Dashboard&quot;">​</a></h2><p>Both paths include the embedded <strong>Kinetic UI</strong> — a React dashboard served directly from the daemon binary via <code>rust-embed</code>.</p><p>With the daemon running, open: <strong><a href="http://localhost:16001" target="_blank" rel="noreferrer">http://localhost:16001</a></strong></p><p>From here you can:</p><ul><li>Monitor DHT peer discovery in real time</li><li>Track active VDF computation progress</li><li>View and manage registered domains</li><li>Inspect heartbeat status for all owned names</li></ul><hr><h2 id="what-you-just-did" tabindex="-1">What You Just Did <a class="header-anchor" href="#what-you-just-did" aria-label="Permalink to &quot;What You Just Did&quot;">​</a></h2><p>You registered a name without:</p><ul><li>A credit card</li><li>A username or account</li><li>Permission from a corporation or government</li><li>Paying anyone, ever</li></ul><p>Your ownership is secured entirely by cryptographic proofs stored across a global decentralized hash table. No ISP can censor your name. No registry can revoke it. No speculator can outbid you.</p><p>Welcome to Kinetic.</p>`,84)])])}const u=i(n,[["render",o]]);export{k as __pageData,u as default};
